-- evt:field
RegisterEvent(15, "Stasis field", function(continueStep)
    if continueStep == 2 then
        evt.SetDoorState(4, DoorAction.Open)
        XeenQuests.hook("m29.stasis")
        evt.SetLight(40012, 0)
        evt.SetMapVar('AmbientSound2', 2)
        return
    end
    if continueStep ~= nil then
        XeenQuests.hook("m29.stasis_wrong")
        return
    end
    if not (not (IsQBitSet(QBit(111582)))) then
        evt.StatusText("The stasis field is down.")
        return
    end
    evt.SetMessage("A strange energy field surrounds a figure suspended within it.")
    evt.AskQuestion(15, 1, 0, 2, "To boldly go...", {"where no man has gone before", "where no man has gone before.", "where no man has gone before!"})
end, "Stasis field")

