-- evt:log3
RegisterEvent(19, "Log Computer", function()
    local page = 1
    for n = 1, 4 do
        if IsAtLeast(MapVar(4), n) then page = n + 1 end
    end
    if page == 1 then
        XeenQuests.hook("m29.log_page_1")
    elseif page == 2 then
        XeenQuests.hook("m29.log_page_2")
    elseif page == 3 then
        XeenQuests.hook("m29.log_page_3")
    elseif page == 4 then
        XeenQuests.hook("m29.log_page_4")
    elseif page == 5 then
        XeenQuests.hook("m29.log_page_5")
    end
    SetValue(MapVar(4), page % 5)
end, "Log Computer")

